-- 210: Kingdom Stories catalogue — 24 categories, planned topics, chapters.
--
-- Structure: Category → Topic → Story → Chapters.
--   • Categories: the existing table (152) gains an optional icon and cover
--     image. 10 of the 13 original categories are the direct equivalent of a
--     new one: they KEEP their id and slug and get the new name, description
--     and order (only while they still carry their original 152 title, so an
--     editor's rename is never overwritten). The other 3 originals are set
--     archived (never deleted) only if no story uses them. The 14 new
--     categories are inserted on slug (skipped if present).
--   • Topics (new): the editorial catalogue of PLANNED stories. Editors only —
--     users never see a topic, only a count of planned topics per category.
--     Seeded with status 'topic' and nothing else invented: period, region
--     and key people are left empty for research.
--   • Stories (152) gain an optional topic_id (administrative; not part of
--     the approval fingerprint).
--   • Chapters (new): number, title, narrative, people/places/dates,
--     Scripture references, separate notes for documented fact, testimony,
--     tradition and disputed claims, and up to 5 Kingdom Lessons and 5 Peer
--     Reflection Questions (exactly 5 + 5 are required to publish).
--   • Sources (152) gain an optional chapter_id (same story enforced by a
--     composite foreign key).
--   • Publishing Studio (188): chapters (and a source's chapter) become part
--     of the approved fingerprint, a live story's chapters are frozen like
--     its media and sources, and a story with an incomplete chapter cannot be
--     published ('chapters_incomplete'). A story WITHOUT chapters hashes
--     exactly as before, so existing approvals stay valid.
--
-- Additive only: no row is deleted; seeding is idempotent (re-running inserts
-- nothing and changes nothing).

-- ── Categories: optional icon and cover image ──────────────────────────────
alter table public.p2p_kingdom_story_categories add column if not exists icon text;
alter table public.p2p_kingdom_story_categories add column if not exists cover_image_path text;

-- ── Topics ─────────────────────────────────────────────────────────────────
create table if not exists public.p2p_kingdom_story_topics (
  id              uuid primary key default gen_random_uuid(),
  slug            text not null unique check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$' and char_length(slug) <= 160),
  title           text not null check (char_length(btrim(title)) between 1 and 200),
  category_id     uuid not null references public.p2p_kingdom_story_categories(id) on delete restrict,
  summary         text,
  tags            text[] not null default '{}',
  historical_period text,
  region          text,
  key_people      text,
  research_notes  text,
  priority        text not null default 'P3' check (priority in ('P1', 'P2', 'P3', 'P4')),
  status          text not null default 'topic'
                  check (status in ('topic', 'researching', 'drafting', 'in_review', 'ready_to_publish', 'published', 'archived')),
  display_order   integer not null default 0,
  overlap_note    text,
  created_by      uuid references auth.users(id) on delete set null,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now()
);
create index if not exists idx_p2p_kingdom_story_topics_category on public.p2p_kingdom_story_topics (category_id, display_order);
create index if not exists idx_p2p_kingdom_story_topics_status on public.p2p_kingdom_story_topics (status);

alter table public.p2p_kingdom_story_topics enable row level security;
-- Explicit grants (never rely on default privileges); RLS below limits
-- signed-in users to editors. The API reads with the service role.
revoke all on public.p2p_kingdom_story_topics from anon;
grant select, insert, update, delete on public.p2p_kingdom_story_topics to authenticated;
grant all on public.p2p_kingdom_story_topics to service_role;
drop policy if exists "Editors read kingdom story topics" on public.p2p_kingdom_story_topics;
create policy "Editors read kingdom story topics" on public.p2p_kingdom_story_topics
  for select to authenticated using (public.p2p_is_kingdom_stories_editor());
drop policy if exists "Editors manage kingdom story topics" on public.p2p_kingdom_story_topics;
create policy "Editors manage kingdom story topics" on public.p2p_kingdom_story_topics
  for all to authenticated using (public.p2p_is_kingdom_stories_editor()) with check (public.p2p_is_kingdom_stories_editor());

-- ── Stories: optional link to their topic ──────────────────────────────────
alter table public.p2p_kingdom_stories
  add column if not exists topic_id uuid references public.p2p_kingdom_story_topics(id) on delete set null;
create index if not exists idx_p2p_kingdom_stories_topic on public.p2p_kingdom_stories (topic_id) where topic_id is not null;

-- ── Chapters ───────────────────────────────────────────────────────────────
create table if not exists public.p2p_kingdom_story_chapters (
  id                  uuid primary key default gen_random_uuid(),
  story_id            uuid not null references public.p2p_kingdom_stories(id) on delete cascade,
  chapter_number      integer not null check (chapter_number > 0),
  title               text not null default '',
  narrative           text not null default '',
  people              text,
  places              text,
  dates               text,
  scripture_refs      text,
  -- What kind of claim each part of the chapter rests on, kept apart so the
  -- reader can tell them apart.
  evidence_documented text,
  evidence_testimony  text,
  evidence_tradition  text,
  evidence_disputed   text,
  lessons             text[] not null default '{}' check (cardinality(lessons) <= 5),
  reflections         text[] not null default '{}' check (cardinality(reflections) <= 5),
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),
  -- Deferrable so chapters can be renumbered (reordered) in one transaction.
  constraint p2p_kingdom_story_chapters_number_unique unique (story_id, chapter_number) deferrable initially immediate,
  constraint p2p_kingdom_story_chapters_id_story unique (id, story_id)
);

alter table public.p2p_kingdom_story_chapters enable row level security;
revoke all on public.p2p_kingdom_story_chapters from anon;
grant select, insert, update, delete on public.p2p_kingdom_story_chapters to authenticated;
grant all on public.p2p_kingdom_story_chapters to service_role;
drop policy if exists "Kingdom story chapters visible with their story" on public.p2p_kingdom_story_chapters;
create policy "Kingdom story chapters visible with their story" on public.p2p_kingdom_story_chapters
  for select using (
    exists (select 1 from public.p2p_kingdom_stories s where s.id = story_id and (s.status = 'published' or public.p2p_is_kingdom_stories_editor()))
  );
drop policy if exists "Editors manage kingdom story chapters" on public.p2p_kingdom_story_chapters;
create policy "Editors manage kingdom story chapters" on public.p2p_kingdom_story_chapters
  for all to authenticated using (public.p2p_is_kingdom_stories_editor()) with check (public.p2p_is_kingdom_stories_editor());

-- A live story's chapters are part of its content: frozen (188's trigger function).
drop trigger if exists trg_p2p_kingdom_story_chapters_freeze on public.p2p_kingdom_story_chapters;
create trigger trg_p2p_kingdom_story_chapters_freeze
  before insert or update or delete on public.p2p_kingdom_story_chapters
  for each row execute function public.p2p_kingdom_story_child_freeze();

-- ── Sources: optional chapter (must be a chapter of the same story) ────────
alter table public.p2p_kingdom_story_sources add column if not exists chapter_id uuid;
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'p2p_kingdom_story_sources_chapter_fk') then
    alter table public.p2p_kingdom_story_sources
      add constraint p2p_kingdom_story_sources_chapter_fk foreign key (chapter_id, story_id)
      references public.p2p_kingdom_story_chapters (id, story_id) on delete cascade;
  end if;
end $$;
create index if not exists idx_p2p_kingdom_story_sources_chapter on public.p2p_kingdom_story_sources (chapter_id) where chapter_id is not null;

-- ── Publishing Studio: fingerprint covers chapters ─────────────────────────
-- Identical to 188 for a story with no chapters and no chapter sources (the
-- 'chapters' key and a source's chapter id are only added when present), so
-- no existing approval goes stale.
create or replace function public.p2p_kingdom_story_fingerprint(s public.p2p_kingdom_stories)
returns text
language sql
stable
set search_path = public, pg_temp
as $$
  select encode(sha256(convert_to((jsonb_build_object(
    'title', s.title, 'subtitle', s.subtitle, 'category_id', s.category_id, 'content_type', s.content_type,
    'body', s.body, 'historical_period', s.historical_period, 'start_year', s.start_year, 'end_year', s.end_year,
    'location', s.location, 'people', s.people, 'learning_section', s.learning_section, 'reflection', s.reflection,
    'scripture_reference_id', s.scripture_reference_id,
    'related_mission_field_id', s.related_mission_field_id, 'related_mission_story_id', s.related_mission_story_id,
    'related_curriculum_id', s.related_curriculum_id, 'related_kingdom_win_id', s.related_kingdom_win_id,
    'related_story_id', s.related_story_id,
    'media', coalesce((select jsonb_agg(jsonb_build_array(m.id, m.media_type, m.media_path, m.caption, m.display_order, m.is_cover, m.duration_seconds) order by m.id)
                       from p2p_kingdom_story_media m where m.story_id = s.id), '[]'::jsonb),
    'sources', coalesce((select jsonb_agg(jsonb_build_array(x.id, x.title, x.publisher, x.url, x.citation, x.source_type, x.display_order)
                                          || case when x.chapter_id is null then '[]'::jsonb else jsonb_build_array(x.chapter_id) end order by x.id)
                         from p2p_kingdom_story_sources x where x.story_id = s.id), '[]'::jsonb)
  ) || coalesce((select jsonb_build_object('chapters', jsonb_agg(jsonb_build_array(
         c.id, c.chapter_number, c.title, c.narrative, c.people, c.places, c.dates, c.scripture_refs,
         c.evidence_documented, c.evidence_testimony, c.evidence_tradition, c.evidence_disputed,
         to_jsonb(c.lessons), to_jsonb(c.reflections)) order by c.chapter_number, c.id))
       from p2p_kingdom_story_chapters c where c.story_id = s.id having count(*) > 0), '{}'::jsonb))::text, 'UTF8')), 'hex');
$$;
revoke all on function public.p2p_kingdom_story_fingerprint(public.p2p_kingdom_stories) from public, anon, authenticated, service_role;

-- Same rules as 188, plus: every chapter complete (title, narrative, exactly
-- 5 non-empty Kingdom Lessons and 5 non-empty Peer Reflection Questions).
create or replace function public.p2p_studio_story_publish_block(p_story public.p2p_kingdom_stories)
returns text
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_item p2p_studio_items;
  v_reviewer_role text;
begin
  select * into v_item from p2p_studio_items where source_type = 'kingdom_story' and source_id = p_story.id;
  if not found or v_item.review_state <> 'approved' then return 'studio_approval_required'; end if;
  if v_item.reviewed_by is null then return 'studio_reviewer_missing'; end if;
  select role into v_reviewer_role from p2p_profiles where id = v_item.reviewed_by;
  if v_reviewer_role is null or v_reviewer_role not in ('admin_content', 'super_admin') then return 'studio_reviewer_ineligible'; end if;
  if v_item.submitted_by is not distinct from v_item.reviewed_by and v_reviewer_role <> 'super_admin' then return 'studio_four_eyes'; end if;
  if v_item.approved_fingerprint is distinct from p2p_kingdom_story_fingerprint(p_story) then return 'studio_approval_stale'; end if;
  if p_story.content_type = 'scripture_story' and p_story.scripture_reference_id is null then return 'scripture_reference_required'; end if;
  if exists (
    select 1 from p2p_kingdom_story_chapters c
     where c.story_id = p_story.id
       and (btrim(c.title) = '' or btrim(c.narrative) = ''
            or cardinality(c.lessons) <> 5 or cardinality(c.reflections) <> 5
            or exists (select 1 from unnest(c.lessons) l where btrim(coalesce(l, '')) = '')
            or exists (select 1 from unnest(c.reflections) r where btrim(coalesce(r, '')) = ''))
  ) then return 'chapters_incomplete'; end if;
  return null;
end;
$$;
revoke all on function public.p2p_studio_story_publish_block(public.p2p_kingdom_stories) from public, anon, authenticated, service_role;

-- Renumber a story's chapters in one transaction (the API calls this after
-- its own editor check; clients cannot).
create or replace function public.p2p_kingdom_story_reorder_chapters(p_story_id uuid, p_chapter_ids uuid[])
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if (select count(*) from p2p_kingdom_story_chapters where story_id = p_story_id) <> cardinality(p_chapter_ids)
     or exists (select 1 from unnest(p_chapter_ids) i where not exists (select 1 from p2p_kingdom_story_chapters c where c.id = i and c.story_id = p_story_id))
     or (select count(distinct i) from unnest(p_chapter_ids) i) <> cardinality(p_chapter_ids) then
    raise exception 'chapter_order_mismatch' using errcode = '22023', hint = 'Send every chapter of this story exactly once.';
  end if;
  set constraints p2p_kingdom_story_chapters_number_unique deferred;
  update p2p_kingdom_story_chapters c set chapter_number = o.n, updated_at = now()
    from unnest(p_chapter_ids) with ordinality as o(id, n)
   where c.id = o.id and c.chapter_number <> o.n;
end;
$$;
revoke all on function public.p2p_kingdom_story_reorder_chapters(uuid, uuid[]) from public, anon, authenticated;
grant execute on function public.p2p_kingdom_story_reorder_chapters(uuid, uuid[]) to service_role;

